import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
page_title="오목 게임 - 2208 이준호",
page_icon="⚫",
layout="centered"
)

html_code = """

<!DOCTYPE html> <html lang="ko"> <head> <meta charset="UTF-8"> <style> * { box-sizing: border-box; } body { margin: 0; background: linear-gradient(135deg, #667eea, #764ba2); font-family: Arial, sans-serif; text-align: center; } .game { padding: 20px 10px; } h1 { color: white; margin: 5px; font-size: 32px; } .name { color: white; font-size: 18px; margin-bottom: 15px; } .info { background: white; padding: 12px; border-radius: 12px; margin: 10px auto 15px; max-width: 500px; font-size: 18px; font-weight: bold; } #message { color: #e74c3c; margin-top: 5px; } /* 오목판 */ #board { width: min(90vw, 600px); height: min(90vw, 600px); margin: auto; display: grid; grid-template-columns: repeat(15, 1fr); grid-template-rows: repeat(15, 1fr); background: #d6a24a; border: 5px solid #6b421e; padding: 8px; box-shadow: 0 10px 25px rgba(0,0,0,0.4); } .cell { position: relative; display: flex; align-items: center; justify-content: center; cursor: pointer; } /* 가로줄 */ .cell::before { content: ""; position: absolute; width: 100%; height: 1px; background: #513517; top: 50%; left: 0; } /* 세로줄 */ .cell::after { content: ""; position: absolute; width: 1px; height: 100%; background: #513517; left: 50%; top: 0; } /* 돌 */ .stone { width: 82%; height: 82%; border-radius: 50%; position: relative; z-index: 2; box-shadow: 2px 3px 5px rgba(0,0,0,0.4); } .black { background: radial-gradient( circle at 30% 30%, #555, #111 60%, #000 ); } .white { background: radial-gradient( circle at 30% 30%, white, #ddd 70%, #aaa ); border: 1px solid #888; } /* 마지막 돌 */ .last { outline: 3px solid red; outline-offset: -3px; } /* 버튼 */ button { margin-top: 20px; padding: 12px 25px; border: none; border-radius: 10px; background: #2ecc71; color: white; font-size: 17px; font-weight: bold; cursor: pointer; } button:hover { background: #27ae60; } </style> </head> <body> <div class="game"> <h1>⚫ 오목 게임 ⚪</h1> <div class="name"> 2208 이준호 </div> <div class="info"> <div id="turn"> 현재 차례: ⚫ 흑돌 </div> <div id="message"></div> </div> <div id="board"></div> <button onclick="restartGame()"> 🔄 다시 시작 </button> </div> <script> const SIZE = 15; let board = []; let player = 1; let gameOver = false; let lastCell = null; // 게임 초기화 function initGame() { board = []; for (let r = 0; r < SIZE; r++) { board[r] = []; for (let c = 0; c < SIZE; c++) { board[r][c] = 0; } } player = 1; gameOver = false; document.getElementById("message").innerText = ""; document.getElementById("turn").innerText = "현재 차례: ⚫ 흑돌"; createBoard(); } // 오목판 생성 function createBoard() { const boardElement = document.getElementById("board"); boardElement.innerHTML = ""; for (let r = 0; r < SIZE; r++) { for (let c = 0; c < SIZE; c++) { const cell = document.createElement("div"); cell.className = "cell"; cell.onclick = function() { putStone(r, c); }; boardElement.appendChild(cell); } } } // 돌 놓기 function putStone(row, col) { if (gameOver) { return; } if (board[row][col] !== 0) { return; } board[row][col] = player; const index = row * SIZE + col; const cell = document.getElementById("board").children[index]; const stone = document.createElement("div"); stone.classList.add("stone"); if (player === 1) { stone.classList.add("black"); } else { stone.classList.add("white"); } cell.appendChild(stone); // 이전 마지막 돌 표시 제거 if (lastCell !== null) { lastCell.classList.remove("last"); } cell.classList.add("last"); lastCell = cell; // 승리 확인 if (checkWin(row, col)) { gameOver = true; const winner = player === 1 ? "⚫ 흑돌" : "⚪ 백돌"; document.getElementById("turn").innerText = "게임 종료"; document.getElementById("message").innerText = "🎉 " + winner + " 승리!"; return; } // 무승부 if (isFull()) { gameOver = true; document.getElementById("turn").innerText = "게임 종료"; document.getElementById("message").innerText = "🤝 무승부입니다!"; return; } // 턴 변경 player = player === 1 ? 2 : 1; if (player === 1) { document.getElementById("turn").innerText = "현재 차례: ⚫ 흑돌"; } else { document.getElementById("turn").innerText = "현재 차례: ⚪ 백돌"; } } // 승리 판정 function checkWin(row, col) { const directions = [ [0, 1], // 가로 [1, 0], // 세로 [1, 1], // 대각선 [1, -1] // 반대 대각선 ]; for (const direction of directions) { const dr = direction[0]; const dc = direction[1]; let count = 1; // 정방향 let r = row + dr; let c = col + dc; while ( r >= 0 && r < SIZE && c >= 0 && c < SIZE && board[r][c] === player ) { count++; r += dr; c += dc; } // 반대 방향 r = row - dr; c = col - dc; while ( r >= 0 && r < SIZE && c >= 0 && c < SIZE && board[r][c] === player ) { count++; r -= dr; c -= dc; } if (count >= 5) { return true; } } return false; } // 판이 꽉 찼는지 확인 function isFull() { for (let r = 0; r < SIZE; r++) { for (let c = 0; c < SIZE; c++) { if (board[r][c] === 0) { return false; } } } return true; } // 다시 시작 function restartGame() { lastCell = null; initGame(); } // 게임 시작 initGame(); </script> </body> </html> """

components.html(
html_code,
height=750,
scrolling=False
)
